package explain_route

import (
	"github.com/MateusMoutinhoOrg/Agnos/sandbox/api"
)

// NewCommand builds this command's declaration — the whole of what its
// entries.yaml says — and closes CommandHandler over the sandbox as the
// handler behind it. It is called once, by sandbox/internal/cli/new.go, and
// what it returns is one entry of Cli.Commands: the declaration alone, which
// the dispatch copies with api.BindCommand before binding a command line onto
// it.
// Generated by `agnos build` — do not edit by hand; the logic
// lives in handler.go.
func NewCommand(sandbox *api.Sandbox) api.Command {
	command := api.NewCommand()

	command.Name = "explain_route"
	command.Identifiers = []string{"explain-route"}
	command.Category = "Server System"
	command.Help = "Show which routes one request reaches, without a server"
	command.LongDescription = "Walks the chain the way the generated dispatch does and prints, route by route, whether it runs for the request or why it is skipped — the segment count, a path that is missing, will not convert or fails its trigger, the method, a parameter trigger — and a 400 its binding would answer. What a handler does once it runs is its own code, so the last line says what the request ends on when none answers. Writes nothing."
	command.Examples = []string{"explain-route GET /admin/users --header 'x-token=abc'"}
	command.Hidden = false

	command.Flags = []api.CommandFlag{
		{
			Id:          "header",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "a header the request carries, as key=value (repeatable)",
			Examples:    []string{"explain-route GET /admin --header 'authorization=Bearer abc'"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--header"},
		},
		{
			Id:          "cookie",
			Type:        "string",
			Required:    false,
			Array:       true,
			Description: "a cookie the request carries, as key=value (repeatable)",
			Examples:    []string{"explain-route GET /admin --cookie session=abc"},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--cookie"},
		},
		{
			Id:          "path",
			Type:        "string",
			Required:    false,
			Array:       false,
			Description: "the dir holding the project (defaults to the current directory)",
			Examples:    []string{"explain-route --path ./my-project"},
			Default:     ".",
			HasDefault:  true,
			Identifiers: []string{"--path"},
		},
		{
			Id:          "quiet",
			Type:        "boolean",
			Required:    false,
			Array:       false,
			Description: "Quiets the cli output",
			Examples:    []string{},
			Default:     "",
			HasDefault:  false,
			Identifiers: []string{"--quiet", "-q"},
		},
	}

	command.Args = []api.CommandArg{
		{
			Id:          "method",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the http method of the request",
			Examples:    []string{"explain-route GET /admin/users"},
			Default:     "",
			HasDefault:  false,
		},
		{
			Id:          "request-path",
			Type:        "string",
			Required:    true,
			Array:       false,
			Description: "the request path, query string included",
			Examples:    []string{"explain-route GET '/articles/42?page=2'"},
			Default:     "",
			HasDefault:  false,
		},
	}

	command.Handler = func(bound *api.Command) int {
		return CommandHandler(sandbox, bound)
	}

	return *command
}
